<div class="ca-agile-page">
    <header class="ca-agile-page-header"><div><span><?= $this->text->e($project['name']) ?></span><h1><?= t('CompanyAgile: Sprints') ?></h1></div><div class="ca-agile-header-actions"><?= $this->url->link(t('CompanyAgile: Backlog'), 'BacklogController', 'show', array('plugin' => 'CompanyAgile', 'project_id' => $project['id']), false, 'btn') ?><?php if ($can_manage_sprints): ?><?= $this->modal->medium('plus', t('CompanyAgile: Create Sprint'), 'SprintController', 'create', array('plugin' => 'CompanyAgile', 'project_id' => $project['id'])) ?><?php endif ?></div></header>
    <div class="ca-sprint-list"><?php foreach ($sprints as $sprint): ?><article class="ca-sprint-summary"><div><span class="ca-status-badge ca-status-<?= $this->text->e($sprint['status']) ?>"><?= t('CompanyAgile sprint status: '.$sprint['status']) ?></span><h2><?= $this->text->e($sprint['name']) ?></h2><?php if ($sprint['goal']): ?><p><?= $this->text->e($sprint['goal']) ?></p><?php endif ?></div><div class="ca-sprint-metrics"><span><?= $this->dt->date($sprint['planned_start_at']) ?> → <?= $this->dt->date($sprint['planned_end_at']) ?></span><strong><?= (int) $sprint['completed_count'] ?> / <?= (int) $sprint['task_count'] ?> <?= t('CompanyAgile: tasks completed') ?></strong><span><?= $this->text->e((float) $sprint['story_points_completed']) ?> / <?= $this->text->e((float) $sprint['story_points_total']) ?> SP</span></div></article><?php endforeach ?><?php if (empty($sprints)): ?><section class="ca-empty-state"><h2><?= t('CompanyAgile: No Sprints yet') ?></h2></section><?php endif ?></div>
</div>
